int add_ipv6_route(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nlmsg_flags & NLM_F_CREATE) == 0 && fib6_lookup_route(root, rt->dst) != NULL) {
        return -EEXIST;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0) {
        return err;
    }

    if (rt->src) {
        struct fib6_node *src_subtree = create_fib6_subtree(rt->src);
        if (!src_subtree) {
            free_fib6_node_resources(root, rt);
            return -ENOMEM;
        }

        err = fib6_add_1(src_subtree, rt, info);
        if (err < 0) {
            free_fib6_node_resources(src_subtree, rt);
            return err;
        }
    }

    increment_route_refcount(rt);
    return 0;
}

int add_new_route(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err = 0;
    struct fib6_node *sroot = NULL;

    if ((info->nlflags & RTM_F_CREATE) == 0) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0) {
        return err;
    }

    if (rt->rt6i_src) {
        sroot = find_subtree_root(rt->rt6i_src);
        if (!sroot) {
            sroot = create_subtree_root();
            if (!sroot) {
                return -ENOMEM;
            }
        }

        err = fib6_add_1(sroot, rt, info);
        if (err < 0) {
            repair_route_tree(root);
            return err;
        }
    }

    rt6_inc_refcnt(rt);
    return 0;
}

int add_fib6_route(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info)
{
    int err;

    if (info->nl_net && (info->nl_net->ipv6.flags & IPV6_RT_F_NOPREFIXROUTE))
        return -EINVAL;

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        return err;

    if (rt->rt6i_src) {
        struct fib6_node *subtree;

        subtree = fib6_find_prefix(root, rt->rt6i_src, rt->rt6i_src_len);
        if (!subtree) {
            subtree = fib6_node_alloc();
            if (!subtree)
                return -ENOMEM;

            subtree->addr = rt->rt6i_src;
            subtree->prefix_len = rt->rt6i_src_len;
            subtree->parent = root;
            list_add(&subtree->list, &root->children);
        }

        err = fib6_add_1(subtree, rt, info);
        if (err < 0) {
            if (subtree && subtree->child_count == 0) {
                list_del(&subtree->list);
                fib6_node_free(subtree);
            }
            return err;
        }
    }

    rt6_update_expires(rt, info);

    return 0;
}

int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info)
{
    int err;

    if ((info->nlflags & NTF_CREATE) || (info->nlflags & NTF_REPLACE)) {
        err = fib6_add_1(root, rt, info);
        if (err < 0)
            return err;

        if (rt->rt6i_src) {
            struct fib6_node *snode;

            snode = fib6_node_create_subtree(root, rt->rt6i_src);
            if (!snode)
                return -ENOMEM;

            err = fib6_add_src_route(snode, rt, info);
            if (err < 0) {
                fib6_node_free_subtree(snode);
                return err;
            }
        }

        rt6_info_inc_ref(rt);
    }

    return 0;
}

int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nlflags & RTM_F_CREATE) == 0 && (info->nlflags & RTM_F_REPLACE) == 0) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0) {
        return err;
    }

    if (rt->rt6i_src) {
        struct fib6_node *subtree = fib6_node_create_subtree(root, rt->rt6i_src);
        if (!subtree) {
            fib6_remove_route(rt);
            return -ENOMEM;
        }

        err = fib6_add_source_route(subtree, rt, info);
        if (err < 0) {
            fib6_remove_route(rt);
            return err;
        }
    }

    return 0;
}
